import { useState } from "react";

function PostForm({ token, onPostAdded, categoryId }) {
    const [title, setTitle] = useState("");
    const [content, setContent] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!categoryId) {
            setError("Оберіть категорію перед створенням поста");
            return;
        }

        if (!title || !content) {
            setError("Заповніть всі поля");
            return;
        }

        setLoading(true);
        try {
            const res = await fetch("http://localhost:5000/api/posts", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ title, content, category_id: categoryId }),
            });

            const data = await res.json();

            if (!res.ok) {
                setError(data.message || "Помилка при створенні поста");
            } else {
                setTitle("");
                setContent("");
                setError("");
                if (onPostAdded) onPostAdded(); // сигналізує App про оновлення
            }
        } catch (err) {
            console.error(err);
            setError("Помилка при запиті до сервера");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="card-gradient rounded-2xl p-6 shadow-xl">
            {error && (
                <div className="mb-4 p-3 bg-red-50 border-l-4 border-red-500 rounded-lg">
                    <p className="text-red-700 text-sm font-medium">{error}</p>
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
                <input
                    type="text"
                    placeholder="Заголовок поста..."
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    className="input-field"
                />
                <textarea
                    placeholder="Що у вас на думці?..."
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    rows={4}
                    className="input-field min-h-[120px] resize-none"
                />
                <button
                    type="submit"
                    disabled={loading}
                    className="btn-primary w-full disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? "Публікуємо..." : "Опублікувати"}
                </button>
            </form>
        </div>
    );
}

export default PostForm;
